import{_ as e,C as t,c as n,o as r,j as i,b as l,a0 as s,a,w as o,G as d,a1 as g}from"./chunks/framework.DKRgXLPU.js";const k=JSON.parse('{"title":"Teknisk træning vs. flowtræning","description":"","frontmatter":{},"headers":[],"relativePath":"da/education/the-zone/technical-vs-flow.md","filePath":"da/education/the-zone/technical-vs-flow.md"}');const u=e({name:"da/education/the-zone/technical-vs-flow.md"},[["render",function(e,k,u,m,f,h){const p=t("Mermaid");return r(),n("div",null,[k[1]||(k[1]=i("h1",{id:"teknisk-træning-vs-flowtræning",tabindex:"-1"},[a("Teknisk træning vs. flowtræning "),i("a",{class:"header-anchor",href:"#teknisk-træning-vs-flowtræning","aria-label":'Permalink to "Teknisk træning vs. flowtræning"'},"​")],-1)),k[2]||(k[2]=i("p",null,"Det er vigtigt at forstå forskellen mellem teknisk træning og flowtræning for eliteudvikling. Begge er nødvendige, men de tjener forskellige formål og kræver forskellige tilgange.",-1)),k[3]||(k[3]=i("div",{class:"tip custom-block"},[i("p",{class:"custom-block-title"},"Kerneprincippet"),i("p",null,[i("strong",null,"Du kan ikke træne en begynder som en ekspert"),a(" (de mangler neurale baner), og "),i("strong",null,"du kan ikke træne en ekspert som en begynder"),a(" (høj teknisk volumen forårsager overtænkning).")])],-1)),(r(),l(g,null,{default:o(()=>[d(p,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BNybegynder%20%3Cbr%2F%3E%2090%25%20Teknologi%5D%20--%3E%20B%5BMellemliggende%20%3Cbr%2F%3E%2070%25%20Teknologi%5D%0A%20%20%20%20B%20--%3E%20C%5BFremskreden%20%3Cbr%2F%3E%2050%25%20Teknologi%5D%0A%20%20%20%20C%20--%3E%20D%5BEkspert%20%3Cbr%2F%3E%2020%25%20Teknologi%5D%0A%0A%20%20%20%20A2%5B10%25%20Mental%5D%20--%3E%20B2%5B30%25%20Mental%5D%0A%20%20%20%20B2%20--%3E%20C2%5B50%25%20Mental%5D%0A%20%20%20%20C2%20--%3E%20D2%5B80%25%20Mental%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffcdd2%0A%20%20%20%20style%20B%20fill%3A%23ffccbc%0A%20%20%20%20style%20C%20fill%3A%23fff9c4%0A%20%20%20%20style%20D%20fill%3A%23c8e6c9%0A%20%20%20%20style%20D2%20fill%3A%23a5d6a7%0A"})]),fallback:o(()=>[...k[0]||(k[0]=[a(" Loading... ",-1)])]),_:1})),k[4]||(k[4]=s('<h2 id="to-typer-træning" tabindex="-1">To typer træning <a class="header-anchor" href="#to-typer-træning" aria-label="Permalink to &quot;To typer træning&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Teknisk træning (eksplicit læring)</p><p><strong>Fokus:</strong> Mekanik og form <strong>Opmærksomhed:</strong> Bevidste kropsbevægelser <strong>Metode:</strong> Nedbrydning af færdigheder, gentagen øvelse <strong>Bedst til:</strong> At lære nye færdigheder, rette op på dårlige vaner, bygge fundament</p><p><strong>Eksempel:</strong> Øv dit frigørelsespunkt 50 gange med videoanalyse</p></div><div class="info custom-block"><p class="custom-block-title">Flowtræning (implicit læring)</p><p><strong>Fokus:</strong> Resultater, ikke mekanik <strong>Opmærksomhed:</strong> At lade underbevidstheden tage over <strong>Metode:</strong> Varieret, spillignende øvelse, visualisering <strong>Bedst til:</strong> Konkurrenceforberedelse, opbygning af selvtillid, toppræstation</p><p><strong>Eksempel:</strong> At spille træningskampe med pres, kun fokusere på mål</p></div><h2 id="den-dynamiske-inversionsmodel" tabindex="-1">Den dynamiske inversionsmodel <a class="header-anchor" href="#den-dynamiske-inversionsmodel" aria-label="Permalink to &quot;Den dynamiske inversionsmodel&quot;">​</a></h2><p>Det korrekte træningsforhold er omvendt korreleret med teknisk kompetence. Efterhånden som du mestrer teknikken, bliver mental træning vigtigere - ikke mindre.</p><h3 id="_1-begynder-kognitivt-stadie" tabindex="-1">1. Begynder (kognitivt stadie) <a class="header-anchor" href="#_1-begynder-kognitivt-stadie" aria-label="Permalink to &quot;1. Begynder (kognitivt stadie)&quot;">​</a></h3><ul><li>Du tænker bevidst over <em>hvad</em> du skal gøre</li><li>Bevægelser føles akavede og kræver indsats</li><li>Hjernen er fuldt mættet med mekanik</li><li><strong>Forhold:</strong> 90% Teknisk / 10% Mental</li><li><strong>Mental fokus:</strong> Nydelse, eksternt fokus (se på målet), ikke kompleks visualisering</li></ul><h3 id="_2-mellemstadiet-associativt-stadie" tabindex="-1">2. Mellemstadiet (Associativt stadie) <a class="header-anchor" href="#_2-mellemstadiet-associativt-stadie" aria-label="Permalink to &quot;2. Mellemstadiet (Associativt stadie)&quot;">​</a></h3><ul><li>Du forfiner færdigheden med mindre bevidst tankegang</li><li>Bevægelser bliver mere jævne, fejl falder</li><li>Du begynder at opdage dine egne fejl</li><li><strong>Forhold:</strong> 70% Teknisk / 30% Mental</li><li><strong>Mental fokus:</strong> Udvikling af din præ-performance rutine (PPR)</li></ul><h3 id="_3-avanceret-tærskel-for-autonomi" tabindex="-1">3. Avanceret (tærskel for autonomi) <a class="header-anchor" href="#_3-avanceret-tærskel-for-autonomi" aria-label="Permalink to &quot;3. Avanceret (tærskel for autonomi)&quot;">​</a></h3><ul><li>Færdigheden er i vid udstrækning automatiseret</li><li>Dit selvbillede halter ofte bagefter dine fysiske evner</li><li>Træningen fokuserer på tryksimulering</li><li><strong>Forhold:</strong> 50% Teknisk / 50% Mental</li><li><strong>Mental fokus:</strong> Visualisering, selvbillede, angstkontrol</li></ul><h3 id="_4-ekspert-autonom-fase" tabindex="-1">4. Ekspert (Autonom fase) <a class="header-anchor" href="#_4-ekspert-autonom-fase" aria-label="Permalink to &quot;4. Ekspert (Autonom fase)&quot;">​</a></h3><ul><li>Tekniske færdigheder er fuldstændig underbevidste</li><li>Bevidst opmærksomhed på mekanik forstyrrer præstationen</li><li>Vedligeholdelsesvolumen er alt, hvad du teknisk set behøver</li><li><strong>Forhold:</strong> 20% Teknisk / 80% Mental</li><li><strong>Mental fokus:</strong> Flowtilstand, strategi, at få sindet til at falde til ro</li></ul><h2 id="progressionstabellen" tabindex="-1">Progressionstabellen <a class="header-anchor" href="#progressionstabellen" aria-label="Permalink to &quot;Progressionstabellen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Niveau</th><th>Teknologi: Mental</th><th>Primært mål</th></tr></thead><tbody><tr><td>Nybegynder</td><td>90 : 10</td><td>Byg maskinen</td></tr><tr><td>Mellemliggende</td><td>70:30</td><td>Stabiliser færdigheden</td></tr><tr><td>Fremskreden</td><td>50:50</td><td>Stol på maskinen</td></tr><tr><td>Ekspert</td><td>20:80</td><td>Frihed til at præstere</td></tr></tbody></table><h2 id="ekspertfælden" tabindex="-1">Ekspertfælden <a class="header-anchor" href="#ekspertfælden" aria-label="Permalink to &quot;Ekspertfælden&quot;">​</a></h2><p>For avancerede og ekspertspillere er det farligt at vende tilbage til et højt teknisk fokus.</p><p><strong>Problemet:</strong> Når du har automatiseret en færdighed, men bevidst overvåger den under konkurrencen, aktiverer du det bevidste sind og tilsidesætter det underbevidste. Dette forårsager præstationsangst og &quot;kvælningsangst&quot;.</p><p><strong>Videnskaben:</strong> Den mængde, der kræves for at vedligeholde en færdighed, er betydeligt lavere (ofte 1/3 til 1/9) end den mængde, der kræves for at opbygge den. Eksperter behøver minimalt teknisk arbejde for at bevare deres touch.</p><p><strong>Eliteeksempel:</strong> Mestre som Philippe Quintais og Dylan Rocher fokuserer i høj grad på taktiske scenarier og kritiske øjeblikke frem for mekaniske øvelser.</p><p>Tegn på, at du overtænker teknikken:</p><ul><li>Lammelse ved analyse</li><li>Ujævn præstation trods god teknik</li><li>Dårligere resultater i konkurrence end i træning</li><li>Følelse af &quot;mekanisk&quot; i stedet for flydende</li></ul><h2 id="sammenligning-af-træningsmetoder" tabindex="-1">Sammenligning af træningsmetoder <a class="header-anchor" href="#sammenligning-af-træningsmetoder" aria-label="Permalink to &quot;Sammenligning af træningsmetoder&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspekt</th><th>Teknisk træning</th><th>Flowtræning</th></tr></thead><tbody><tr><td><strong>Øvelsestype</strong></td><td>Blokeret (samme færdighed gentagne gange)</td><td>Tilfældige (varierede færdigheder)</td></tr><tr><td><strong>Feedback</strong></td><td>Øjeblikkelig, detaljeret</td><td>Forsinket, resultatfokuseret</td></tr><tr><td><strong>Miljø</strong></td><td>Kontrolleret, forudsigelig</td><td>Variabel, spillignende</td></tr><tr><td><strong>Mental tilstand</strong></td><td>Analytisk, bevidst</td><td>Intuitiv, automatisk</td></tr><tr><td><strong>Bedste tidspunkt</strong></td><td>Uden for sæsonen, færdighedsopbygning</td><td>Før konkurrence, vedligeholdelse</td></tr></tbody></table><h2 id="blokeret-vs-tilfældig-øvelse" tabindex="-1">Blokeret vs. tilfældig øvelse <a class="header-anchor" href="#blokeret-vs-tilfældig-øvelse" aria-label="Permalink to &quot;Blokeret vs. tilfældig øvelse&quot;">​</a></h2><p><strong>Blokeret øvelse:</strong> Gentag det samme kast 20 gange</p><ul><li>Føles produktiv (du ser hurtig forbedring)</li><li>God til indledende læring</li><li>Dårlig til langsigtet fastholdelse</li></ul><p><strong>Tilfældig øvelse:</strong> Varier afstand, mål og kastetype</p><ul><li>Føles sværere (flere fejl)</li><li>Bedre til konkurrencetransfer</li><li>Opbygger tilpasningsevne og beslutningstagning</li></ul><h2 id="praktiske-retningslinjer" tabindex="-1">Praktiske retningslinjer <a class="header-anchor" href="#praktiske-retningslinjer" aria-label="Permalink to &quot;Praktiske retningslinjer&quot;">​</a></h2><h3 id="til-tekniske-sessioner" tabindex="-1">Til tekniske sessioner <a class="header-anchor" href="#til-tekniske-sessioner" aria-label="Permalink to &quot;Til tekniske sessioner&quot;">​</a></h3><ol><li>Fokuser på ÉT aspekt ad gangen</li><li>Brug videoanalyse</li><li>Få feedback fra en træner eller træningspartner</li><li>Accepter at det vil føles akavet i starten</li><li>Hold sessionerne kortere (kvalitet frem for kvantitet)</li></ol><h3 id="til-flowsessioner" tabindex="-1">Til flowsessioner <a class="header-anchor" href="#til-flowsessioner" aria-label="Permalink to &quot;Til flowsessioner&quot;">​</a></h3><ol><li>Skab et pres i et spil</li><li>Fokuser på målet, ikke din krop</li><li>Brug din rutine før indsprøjtning konsekvent</li><li>Analysér ikke under sessionen</li><li>Stol på din træning</li></ol><h2 id="integrationsudfordringen" tabindex="-1">Integrationsudfordringen <a class="header-anchor" href="#integrationsudfordringen" aria-label="Permalink to &quot;Integrationsudfordringen&quot;">​</a></h2><p>Den virkelige færdighed er at vide, hvornår man skal bruge hver tilstand:</p><p><strong>Under en konkurrencekamp:</strong></p><ul><li>Teknisk tænkning: ALDRIG under udførelsen</li><li>Flowtilstand: ALTID når man kaster</li></ul><p><strong>Under træning:</strong></p><ul><li>Tekniske sessioner: Planlagt, specifikt fokus</li><li>Flowsessioner: Spilsimulering, trykøvelser</li></ul><h2 id="eksempel-pa-ugentlig-saldo" tabindex="-1">Eksempel på ugentlig saldo <a class="header-anchor" href="#eksempel-pa-ugentlig-saldo" aria-label="Permalink to &quot;Eksempel på ugentlig saldo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dag</th><th>Sessionstype</th><th>Fokus</th></tr></thead><tbody><tr><td>mandag</td><td>Teknisk</td><td>Pegepræcision</td></tr><tr><td>tirsdag</td><td>Teknisk</td><td>Skydepræcision</td></tr><tr><td>onsdag</td><td>Flyde</td><td>Mental træning, visualisering</td></tr><tr><td>torsdag</td><td>Blandet</td><td>Spilscenarier med fokus på flow</td></tr><tr><td>fredag</td><td>Teknisk</td><td>Svaghedsområde</td></tr><tr><td>lørdag</td><td>Flyde</td><td>Matchspil, konkurrencesimulering</td></tr><tr><td>søndag</td><td>Hvile</td><td>Genopretning, refleksion</td></tr></tbody></table><h2 id="resume-regler-for-træningsbalance" tabindex="-1">Resumé: Regler for træningsbalance <a class="header-anchor" href="#resume-regler-for-træningsbalance" aria-label="Permalink to &quot;Resumé: Regler for træningsbalance&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Regel nr. 1: Match træningen til niveau</p><p><strong>Begyndere (90/10):</strong> Byg maskinen - fokuser på teknik <strong>Mellem (70/30):</strong> Stabiliser færdigheden - tilføj mentalt arbejde <strong>Avanceret (50/50):</strong> Stol på maskinen - balancer begge dele <strong>Ekspert (20/80):</strong> Præstationsfrihed - primært mental</p></div><div class="tip custom-block"><p class="custom-block-title">Regel nr. 2: Blokeret vs. tilfældig øvelse</p><p><strong>Blokeret øvelse</strong> (samme kast gentagne gange): God til indledende læring, dårlig til fastholdelse <strong>Tilfældig træning</strong> (varierede kast): Sværere i træning, bedre i konkurrence</p></div><div class="tip custom-block"><p class="custom-block-title">Regel nr. 3: Ekspertfælden</p><p><strong>For eksperter:</strong> Høj teknisk volumen forårsager overtænkning og kvælning <strong>Løsning:</strong> Minimal teknisk vedligeholdelse, maksimal mental træning</p></div><h2 id="vigtig-konklusion" tabindex="-1">Vigtig konklusion <a class="header-anchor" href="#vigtig-konklusion" aria-label="Permalink to &quot;Vigtig konklusion&quot;">​</a></h2><blockquote><p>Du kan ikke træne en begynder som en ekspert (de mangler de neurale baner til mentalt arbejde), og du kan ikke træne en ekspert som en begynder (høj teknisk volumen forårsager udbrændthed og overtænkning).</p></blockquote><p>Rejsen fra teknik til flow kræver strategisk inversion. Tilpas din træning til dit udviklingstrin.</p>',49))])}]]);export{k as __pageData,u as default};
